#include <WiFi.h>
#include <PubSubClient.h>
WiFiClient net; PubSubClient mqtt(net);

void setup() {
  Serial.begin(115200);
  WiFi.begin("{{ssid}}", "{{password}}");
  while (WiFi.status() != WL_CONNECTED) delay(300);
  mqtt.setServer("{{broker}}", 1883);
  while (!mqtt.connect("{{sensor_id}}")) delay(500);
  String cfgTopic = String("homeassistant/sensor/{{sensor_id}}/config");
  String stTopic = String("home/{{sensor_id}}/state");
  String cfg = String("{\"name\":\"{{sensor_id}}\",\"state_topic\":\"") + stTopic + "\",\"unit_of_measurement\":\"C\"}";
  mqtt.publish(cfgTopic.c_str(), cfg.c_str(), true);
  mqtt.publish(stTopic.c_str(), "23.5");
}

void loop() { mqtt.loop(); }
